using namespace std;

class l2_flash_attention_score_enhance_test : public testing::Test
{
protected:
    static void SetUpTestCase()
    {
        cout << "l2_flash_attention_score_enhance_test SetUp" << endl;
    }

    static void TearDownTestCase()
    {
        cout << "l2_flash_attention_score_enhance_test TearDown" << endl;
    }
};

// 全量化 kvcache pertensor量化
TEST_F(l2_flash_attention_score_enhance_test, Ascend910B2_flash_attention_score_enhance_0)
{
    std::vector<int64_t> actualSeqLengthsArray = {256};
    std::vector<int64_t> actualSeqLengthsKvArray = {256};
    auto query = TensorDesc({256, 2, 192}, ACL_BF16, ACL_FORMAT_ND).ValueRange(-1,1);
    auto queryRope = nullptr;
    auto key = TensorDesc({384, 2, 192}, ACL_BF16, ACL_FORMAT_ND).ValueRange(-1,1);
    auto keyRope = nullptr;
    auto value = TensorDesc({384, 2, 192}, ACL_BF16, ACL_FORMAT_ND).ValueRange(-1,1);
    auto realShiftOptional = nullptr;
    auto dropMaskOptional = nullptr;
    auto paddingMaskOptional = nullptr;
    auto attenMaskOptional = TensorDesc({2048, 2048}, ACL_BOOL, ACL_FORMAT_ND);
    auto sinkOptional = nullptr;
    auto prefixOptional = nullptr;
    aclIntArray * actualSeqQLenOptional = aclCreateIntArray(actualSeqLengthsArray.data(), actualSeqLengthsArray.size());
    aclIntArray * actualSeqKvLenOptional = aclCreateIntArray(actualSeqLengthsKvArray.data(), actualSeqLengthsKvArray.size());
    auto qStartIdxOptional = nullptr;
    auto kvStartIdxOptional = nullptr;
    auto softmaxMaxOut = TensorDesc({256, 2, 8}, ACL_BF16, ACL_FORMAT_ND);
    auto softmaxSumOut = TensorDesc({256, 2, 8}, ACL_FLOAT, ACL_FORMAT_ND);
    auto softmaxOutOut = TensorDesc({0,0,0}, ACL_BF16, ACL_FORMAT_ND);
    auto attentionOutOut = TensorDesc({256, 2, 192}, ACL_FLOAT, ACL_FORMAT_ND);

    double scaleValue = 0.0721687;
    double keepProb = 1.0;
    int64_t preTokens = 65536;
    int64_t nextTokens = 65536;
    int64_t headNum = 2;
    char *inputLayout = "TND";
    int64_t innerPrecise = 0;
    int64_t sparseMode = 2;
    int64_t pseType = 1;
    char *softmaxOutLayout = "";
    int64_t sinkNum = 2;

    auto ut = OP_API_UT(
        aclnnFlashAttentionVarLenScoreEnhanceV5,
        INPUT(
            query,
            queryRope,
            key,
            keyRope,
            value,
            realShiftOptional,
            dropMaskOptional,
            paddingMaskOptional,
            attenMaskOptional,
            sinkOptional,
            prefixOptional,
            actualSeqQLenOptional,
            actualSeqKvLenOptional,
            qStartIdxOptional,
            kvStartIdxOptional,
            scaleValue,
            keepProb,
            preTokens,
            nextTokens,
            headNum,
            inputLayout,
            innerPrecise,
            sparseMode,
            pseType,
            softmaxOutLayout,
            sinkNum),
        OUTPUT(softmaxMaxOut, softmaxSumOut, softmaxOutOut, attentionOutOut));
    uint64_t workspaceSize = 0;
    aclOpExecutor* executor = nullptr;
    aclnnStatus getWorkspaceResult = ut.TestGetWorkspaceSizeWithNNopbaseInner(&workspaceSize, executor);
    EXPECT_EQ(getWorkspaceResult, ACLNN_SUCCESS);
    // uint64_t workspaceSize = 0;
    // aclnnStatus aclRet = ut.TestGetWorkspaceSize(&workspaceSize);
    // EXPECT_EQ(aclRet, ACL_SUCCESS);
}

